INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('eventually', 3, 'We tried a few solutions and eventually fixed the problem.', 'Chúng tôi đã thử một vài giải pháp và cuối cùng đã khắc phục được sự cố.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('eventually', 4, 'We checked our tickets and eventually left for the station.', 'Chúng tôi kiểm tra vé và cuối cùng lên đường đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('eventually', 5, 'I used the word eventually when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "cuối cùng" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('finally', 1, 'Finally, I finished work!', 'Cuối cùng cũng xong việc!');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('finally', 2, 'I finally finished the report before the deadline.', 'Cuối cùng thì tôi cũng hoàn thành báo cáo trước hạn chót.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('finally', 3, 'She finally called the client back.', 'Cuối cùng, cô ấy cũng gọi lại cho khách hàng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('finally', 4, 'We checked our tickets and finally left for the station.', 'Chúng tôi kiểm tra vé và cuối cùng cũng lên đường đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('finally', 5, 'I used the word finally when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "cuối cùng" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('suddenly', 1, 'Suddenly, it started raining.', 'Đột nhiên trời đổ mưa.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('suddenly', 2, 'The power suddenly went out during the meeting.', 'Đột nhiên mất điện trong cuộc họp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('suddenly', 3, 'He suddenly remembered the appointment.', 'Anh ấy chợt nhớ ra cuộc hẹn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('suddenly', 4, 'We checked our tickets and suddenly left for the station.', 'Chúng tôi kiểm tra vé và đột nhiên rời đi đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('suddenly', 5, 'I used the word suddenly when I talked with my coworker about our trip.', 'Tôi đã dùng từ "đột nhiên" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('recently', 1, 'I haven''t seen him recently.', 'Gần đây tôi không gặp anh ấy.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('recently', 2, 'I recently started a new job.', 'Gần đây tôi bắt đầu một công việc mới.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('recently', 3, 'Have you spoken with the manager recently?', 'Gần đây bạn có nói chuyện với người quản lý không?');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('recently', 4, 'We checked our tickets and recently left for the station.', 'Chúng tôi đã kiểm tra vé và vừa mới rời đi để đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('recently', 5, 'I used the word recently when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "gần đây" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('lately', 1, 'What have you been doing lately?', 'Dạo này bạn làm gì?');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('lately', 2, 'I have been working late a lot lately.', 'Gần đây, tôi thường xuyên làm việc muộn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('lately', 3, 'Have you been sleeping well lately?', 'Gần đây bạn có ngủ ngon không?');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('lately', 4, 'We checked our tickets and lately left for the station.', 'Chúng tôi kiểm tra vé và sau đó mới rời đi đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('lately', 5, 'I used the word lately when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "gần đây" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('gradually', 1, 'My English is gradually getting better.', 'Tiếng Anh của tôi đang dần tốt lên.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('gradually', 2, 'Her confidence gradually grew after more practice.', 'Sự tự tin của cô ấy dần tăng lên sau khi luyện tập nhiều hơn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('gradually', 3, 'We are gradually improving the process.', 'Chúng tôi đang dần cải thiện quy trình.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('gradually', 4, 'We checked our tickets and gradually left for the station.', 'Chúng tôi kiểm tra vé và dần dần rời đi để đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('gradually', 5, 'I used the word gradually when I talked with my coworker about our trip.', 'Tôi đã dùng từ "dần dần" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('immediately', 1, 'Call me immediately if you need help.', 'Gọi tôi ngay nếu cần giúp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('immediately', 2, 'Please contact me immediately if anything changes.', 'Vui lòng liên hệ với tôi ngay lập tức nếu có bất kỳ thay đổi nào.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('immediately', 3, 'The team acted immediately after the issue was reported.', 'Nhóm đã hành động ngay sau khi vấn đề được báo cáo.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('immediately', 4, 'We checked our tickets and immediately left for the station.', 'Chúng tôi kiểm tra vé và lập tức lên đường đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('immediately', 5, 'I used the word immediately when I talked with my coworker about our trip.', 'Tôi đã dùng từ "ngay lập tức" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('soon', 1, 'I''ll be home soon.', 'Tôi sẽ về nhà sớm thôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('soon', 2, 'I will send you the updated file soon.', 'Tôi sẽ sớm gửi cho bạn tệp đã cập nhật.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('soon', 3, 'The train should arrive soon.', 'Chuyến tàu sắp đến rồi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('soon', 4, 'We checked our tickets and soon left for the station.', 'Chúng tôi kiểm tra vé và sớm lên đường đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('soon', 5, 'I used the word soon when I talked with my coworker about our trip.', 'Tôi đã dùng từ "chẳng bao lâu nữa" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('yet', 1, 'I haven''t eaten yet.', 'Tôi vẫn chưa ăn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('yet', 2, 'I have not heard back from the manager yet.', 'Tôi vẫn chưa nhận được phản hồi từ người quản lý.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('yet', 3, 'Have you finished the report yet?', 'Bạn đã hoàn thành báo cáo chưa?');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('yet', 4, 'We checked our tickets and yet left for the station.', 'Chúng tôi đã kiểm tra vé và vẫn lên đường đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('yet', 5, 'I used the word yet when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "yet" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('already', 1, 'I already told you.', 'Tôi nói với bạn rồi mà.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('already', 2, 'I have already sent the invoice.', 'Tôi đã gửi hóa đơn rồi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('already', 3, 'They are already waiting for us.', 'Họ đã chờ chúng ta rồi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('already', 4, 'We checked our tickets and already left for the station.', 'Chúng tôi đã kiểm tra vé và đã rời đi đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('already', 5, 'I used the word already when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "đã" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('still', 1, 'Are you still working?', 'Bạn vẫn đang làm việc à?');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('still', 2, 'She is still working on the presentation.', 'Cô ấy vẫn đang làm bài thuyết trình.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('still', 3, 'The shop is still open.', 'Cửa hàng vẫn còn mở cửa.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('still', 4, 'We checked our tickets and still left for the station.', 'Chúng tôi kiểm tra vé và vẫn lên đường đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('still', 5, 'I used the word still when I talked with my coworker about our trip.', 'Tôi đã dùng từ "vẫn" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('anymore', 1, 'I don''t live there anymore.', 'Tôi không sống ở đó nữa.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('anymore', 2, 'He does not work here anymore.', 'Anh ấy không còn làm việc ở đây nữa.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('anymore', 3, 'I do not use that app anymore.', 'Tôi không còn sử dụng ứng dụng đó nữa.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('anymore', 4, 'We checked our tickets and anymore left for the station.', 'Chúng tôi đã kiểm tra vé và không còn vé nào nữa để đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('anymore', 5, 'I used the word anymore when I talked with my coworker about our trip.', 'Tôi đã sử dụng cụm từ "anymore" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('once', 1, 'Once you try it, you''ll love it.', 'Một khi bạn thử, bạn sẽ thích nó.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('once', 2, 'Once you submit the form, you will get a confirmation email.', 'Sau khi gửi biểu mẫu, bạn sẽ nhận được email xác nhận.');
