INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('once', 4, 'We checked our tickets and once left for the station.', 'Chúng tôi kiểm tra vé và ngay lập tức lên đường đến nhà ga.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('once', 5, 'I used the word once when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "một lần" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('twice', 1, 'I''ve been there twice.', 'Tôi đã đến đó hai lần.');
