INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('twice', 5, 'I used the word twice when I talked with my coworker about our trip.', 'Tôi đã dùng từ "hai lần" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('really', 1, 'I''m really tired.', 'Tôi thực sự rất mệt.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('really', 2, 'I really appreciate your help.', 'Tôi thực sự cảm kích sự giúp đỡ của bạn.');
