INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('really', 4, 'The new booking website is really easy to use.', 'Trang web đặt phòng mới thực sự dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('really', 5, 'I used the word really when I talked with my coworker about our trip.', 'Tôi đã dùng từ "thực sự" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('very', 1, 'It''s very hot today.', 'Hôm nay rất nóng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('very', 2, 'We had a very productive meeting.', 'Chúng tôi đã có một cuộc họp rất hiệu quả.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('very', 3, 'The instructions are very clear.', 'Các hướng dẫn rất rõ ràng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('very', 4, 'The new booking website is very easy to use.', 'Trang web đặt phòng mới rất dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('very', 5, 'I used the word very when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "rất" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('quite', 1, 'It''s quite expensive.', 'Nó khá đắt.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('quite', 2, 'The new software is quite easy to use.', 'Phần mềm mới khá dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('quite', 3, 'The office is quite busy today.', 'Hôm nay văn phòng khá bận rộn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('quite', 4, 'The new booking website is quite easy to use.', 'Trang web đặt phòng mới khá dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('quite', 5, 'I used the word quite when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "khá" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('pretty', 1, 'I''m pretty sure.', 'Tôi khá chắc.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('pretty', 2, 'The commute is pretty short from my apartment.', 'Quãng đường đi làm từ căn hộ của tôi khá ngắn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('pretty', 3, 'I am pretty sure I sent that email.', 'Tôi khá chắc là tôi đã gửi email đó.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('pretty', 4, 'The new booking website is pretty easy to use.', 'Trang web đặt chỗ mới khá dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('pretty', 5, 'I used the word pretty when I talked with my coworker about our trip.', 'Tôi đã dùng từ "khá" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('just', 1, 'I just got home.', 'Tôi vừa mới về nhà.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('just', 2, 'I just finished a call with the client.', 'Tôi vừa kết thúc cuộc gọi với khách hàng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('just', 3, 'The office is just around the corner.', 'Văn phòng chỉ cách đây một quãng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('just', 4, 'The new booking website is just easy to use.', 'Trang web đặt phòng mới rất dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('just', 5, 'I used the word just when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "just" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('almost', 1, 'I almost forgot.', 'Tôi suýt thì quên.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('almost', 2, 'I am almost ready for the meeting.', 'Tôi gần như đã sẵn sàng cho cuộc họp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('almost', 3, 'We almost missed the train.', 'Chúng tôi suýt nữa thì lỡ chuyến tàu.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('almost', 4, 'The new booking website is almost easy to use.', 'Trang web đặt phòng mới gần như dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('almost', 5, 'I used the word almost when I talked with my coworker about our trip.', 'Tôi đã dùng từ "gần như" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('completely', 1, 'I completely forgot.', 'Tôi quên hoàn toàn luôn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('completely', 2, 'I completely understand your concern.', 'Tôi hoàn toàn hiểu mối lo ngại của bạn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('completely', 3, 'The schedule has completely changed.', 'Lịch trình đã thay đổi hoàn toàn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('completely', 4, 'The new booking website is completely easy to use.', 'Trang web đặt phòng mới hoàn toàn dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('completely', 5, 'I used the word completely when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "hoàn toàn" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('totally', 1, 'I totally agree.', 'Tôi hoàn toàn đồng ý.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('totally', 2, 'I totally understand what you mean.', 'Tôi hoàn toàn hiểu ý của anh.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('totally', 3, 'The two plans are totally different.', 'Hai gói hoàn toàn khác nhau.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('totally', 4, 'The new booking website is totally easy to use.', 'Trang web đặt phòng mới hoàn toàn dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('totally', 5, 'I used the word totally when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "hoàn toàn" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_relations (word, relation_type, value) VALUES ('totally', 'synonym', 'completely');
INSERT INTO hard_word_relations (word, relation_type, value) VALUES ('totally', 'synonym', 'entirely');
INSERT INTO hard_word_relations (word, relation_type, value) VALUES ('totally', 'synonym', 'fully');
