INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('extremely', 1, 'I''m extremely busy.', 'Tôi cực kỳ bận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('extremely', 2, 'The deadline is extremely tight.', 'Hạn chót rất gấp gáp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('extremely', 3, 'She was extremely helpful during onboarding.', 'Cô ấy đã hỗ trợ rất nhiều trong quá trình đào tạo nhập môn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('extremely', 4, 'The new booking website is extremely easy to use.', 'Trang web đặt phòng mới cực kỳ dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('extremely', 5, 'I used the word extremely when I talked with my coworker about our trip.', 'Tôi đã dùng từ "cực kỳ" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('especially', 1, 'I love coffee, especially in the morning.', 'Tôi thích cafe, đặc biệt là buổi sáng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('especially', 2, 'I enjoy this caf?, especially after work.', 'Tôi thích quán cà phê này, đặc biệt là sau giờ làm việc.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('especially', 3, 'This shortcut is especially useful on busy days.', 'Lối tắt này đặc biệt hữu ích vào những ngày bận rộn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('especially', 4, 'The new booking website is especially easy to use.', 'Trang web đặt chỗ mới đặc biệt dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('especially', 5, 'I used the word especially when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "đặc biệt" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('particularly', 1, 'Not particularly.', 'Không đặc biệt lắm.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('particularly', 2, 'I am not particularly worried about the change.', 'Tôi không đặc biệt lo lắng về sự thay đổi này.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('particularly', 3, 'We need to be particularly careful with customer data.', 'Chúng ta cần đặc biệt cẩn trọng với dữ liệu khách hàng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('particularly', 4, 'The new booking website is particularly easy to use.', 'Trang web đặt chỗ mới đặc biệt dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('particularly', 5, 'I used the word particularly when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "đặc biệt" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_relations (word, relation_type, value) VALUES ('particularly', 'synonym', 'especially');
