INSERT INTO hard_word_relations (word, relation_type, value) VALUES ('particularly', 'antonym', 'usually');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mainly', 1, 'I mainly work from home.', 'Tôi chủ yếu làm việc ở nhà.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mainly', 2, 'I mainly work with customers by email.', 'Tôi chủ yếu làm việc với khách hàng qua email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mainly', 3, 'The meeting is mainly about next quarter''s budget.', 'Cuộc họp chủ yếu xoay quanh ngân sách của quý tới.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mainly', 4, 'The new booking website is mainly easy to use.', 'Trang web đặt chỗ mới chủ yếu là dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mainly', 5, 'I used the word mainly when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "chủ yếu" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mostly', 1, 'It''s mostly my fault.', 'Hầu hết là lỗi của tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mostly', 2, 'The team is mostly based in Bangkok.', 'Nhóm chủ yếu làm việc tại Bangkok.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mostly', 3, 'I mostly cook at home during the week.', 'Tôi chủ yếu nấu ăn ở nhà vào các ngày trong tuần.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mostly', 4, 'The new booking website is mostly easy to use.', 'Trang web đặt phòng mới phần lớn là dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mostly', 5, 'I used the word mostly when I talked with my coworker about our trip.', 'Tôi đã dùng cụm từ "chủ yếu" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('exactly', 1, 'That''s exactly what I meant.', 'Đó chính xác là ý tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('exactly', 2, 'That is exactly what the client requested.', 'Đó chính xác là điều mà khách hàng đã yêu cầu.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('exactly', 3, 'I know exactly where I saved the file.', 'Tôi biết chính xác nơi tôi đã lưu tệp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('exactly', 4, 'The new booking website is exactly easy to use.', 'Trang web đặt chỗ mới rất dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('exactly', 5, 'I used the word exactly when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "chính xác" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('hardly', 1, 'I hardly sleep.', 'Tôi hầu như không ngủ.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('hardly', 2, 'I hardly had time to eat before the meeting.', 'Tôi hầu như không có thời gian để ăn trước cuộc họp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('hardly', 3, 'We hardly ever see each other during the week.', 'Chúng tôi hầu như không gặp nhau trong tuần.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('hardly', 4, 'The new booking website is hardly easy to use.', 'Trang web đặt chỗ mới hầu như không dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('hardly', 5, 'I used the word hardly when I talked with my coworker about our trip.', 'Tôi đã dùng từ "hardly" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('barely', 1, 'I barely passed.', 'Tôi vừa đủ điểm qua môn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('barely', 2, 'I barely caught the last bus home.', 'Tôi suýt chút nữa thì lỡ chuyến xe buýt cuối cùng về nhà.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('barely', 3, 'The new laptop barely fits in my bag.', 'Chiếc laptop mới gần như không vừa túi của tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('barely', 4, 'The new booking website is barely easy to use.', 'Trang web đặt chỗ mới hầu như không dễ sử dụng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('barely', 5, 'I used the word barely when I talked with my coworker about our trip.', 'Tôi đã dùng từ "hầu như không" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('actually', 1, 'Actually, I don''t like it.', 'Thực ra tôi không thích nó.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('actually', 2, 'I will actually let you know when the meeting is confirmed.', 'Tôi sẽ thông báo cho anh/chị khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('actually', 3, 'We actually check the details before sending the email.', 'Thực ra, chúng tôi kiểm tra thông tin trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('actually', 4, 'I actually thought the email was urgent, but it could wait.', 'Thực ra tôi nghĩ email đó là khẩn cấp, nhưng nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('actually', 5, 'I used the word actually when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "actually" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('basically', 1, 'Basically, we need more time.', 'Về cơ bản, chúng ta cần thêm thời gian.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('basically', 2, 'I will basically let you know when the meeting is confirmed.', 'Về cơ bản, tôi sẽ thông báo cho bạn khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('basically', 3, 'We basically check the details before sending the email.', 'Về cơ bản, chúng tôi kiểm tra thông tin trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('basically', 4, 'I basically thought the email was urgent, but it could wait.', 'Về cơ bản, tôi nghĩ rằng email đó là khẩn cấp, nhưng nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('basically', 5, 'I used the word basically when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "về cơ bản" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('honestly', 1, 'Honestly, I don''t know.', 'Nói thật thì tôi không biết.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('honestly', 2, 'I will honestly let you know when the meeting is confirmed.', 'Tôi sẽ thành thật báo cho anh/chị khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('honestly', 3, 'We honestly check the details before sending the email.', 'Chúng tôi kiểm tra kỹ các chi tiết trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('honestly', 4, 'I honestly thought the email was urgent, but it could wait.', 'Tôi thực sự nghĩ rằng email đó là khẩn cấp, nhưng hóa ra nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('honestly', 5, 'I used the word honestly when I talked with my coworker about our trip.', 'Tôi đã dùng từ "thành thật" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('frankly', 1, 'Frankly, it''s not good.', 'Thẳng thắn mà nói thì nó không tốt.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('frankly', 2, 'I will frankly let you know when the meeting is confirmed.', 'Tôi sẽ thẳng thắn cho bạn biết khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('frankly', 3, 'We frankly check the details before sending the email.', 'Chúng tôi kiểm tra kỹ các chi tiết trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('frankly', 4, 'I frankly thought the email was urgent, but it could wait.', 'Thành thật mà nói, tôi nghĩ email đó rất gấp, nhưng nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('frankly', 5, 'I used the word frankly when I talked with my coworker about our trip.', 'Tôi đã dùng từ "thẳng thắn" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
