INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('clearly', 1, 'Clearly, we have a problem.', 'Rõ ràng chúng ta có vấn đề.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('clearly', 2, 'I will clearly let you know when the meeting is confirmed.', 'Tôi sẽ thông báo rõ ràng cho bạn khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('clearly', 3, 'We clearly check the details before sending the email.', 'Chúng tôi kiểm tra kỹ các chi tiết trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('clearly', 4, 'I clearly thought the email was urgent, but it could wait.', 'Tôi rõ ràng nghĩ rằng email đó là khẩn cấp, nhưng nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('clearly', 5, 'I used the word clearly when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "rõ ràng" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('definitely', 1, 'I''ll definitely come.', 'Tôi chắc chắn sẽ đến.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('definitely', 2, 'I will definitely let you know when the meeting is confirmed.', 'Tôi chắc chắn sẽ báo cho bạn khi cuộc họp được xác nhận.');
