INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('possibly', 1, 'Possibly, but I''m not sure.', 'Có thể, nhưng tôi không chắc.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('possibly', 2, 'I will possibly let you know when the meeting is confirmed.', 'Có lẽ tôi sẽ báo cho anh/chị khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('possibly', 3, 'We possibly check the details before sending the email.', 'Có lẽ chúng ta sẽ kiểm tra thông tin trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('possibly', 4, 'I possibly thought the email was urgent, but it could wait.', 'Có lẽ tôi đã nghĩ rằng email đó là khẩn cấp, nhưng nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('possibly', 5, 'I used the word possibly when I talked with my coworker about our trip.', 'Tôi đã dùng từ "có thể" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('maybe', 1, 'Maybe we should go.', 'Có thể chúng ta nên đi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('maybe', 2, 'I will maybe let you know when the meeting is confirmed.', 'Có lẽ tôi sẽ báo cho bạn khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('maybe', 3, 'We maybe check the details before sending the email.', 'Có lẽ chúng ta sẽ kiểm tra thông tin chi tiết trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('maybe', 4, 'I maybe thought the email was urgent, but it could wait.', 'Có lẽ tôi đã nghĩ rằng email đó là khẩn cấp, nhưng nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('maybe', 5, 'I used the word maybe when I talked with my coworker about our trip.', 'Tôi đã dùng từ "có lẽ" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('hopefully', 1, 'Hopefully, it won''t rain.', 'Hy vọng là trời không mưa.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('hopefully', 2, 'I will hopefully let you know when the meeting is confirmed.', 'Hy vọng là tôi sẽ báo cho bạn khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('hopefully', 3, 'We hopefully check the details before sending the email.', 'Hy vọng là chúng ta sẽ kiểm tra thông tin trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('hopefully', 4, 'I hopefully thought the email was urgent, but it could wait.', 'Tôi hy vọng là mình đã nghĩ rằng email đó là khẩn cấp, nhưng nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('hopefully', 5, 'I used the word hopefully when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "hy vọng" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('fortunately', 1, 'Fortunately, I found my phone.', 'May mắn là tôi tìm thấy điện thoại.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('fortunately', 2, 'I will fortunately let you know when the meeting is confirmed.', 'Tôi sẽ thông báo cho bạn khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('fortunately', 3, 'We fortunately check the details before sending the email.', 'May mắn thay, chúng tôi kiểm tra thông tin chi tiết trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('fortunately', 4, 'I fortunately thought the email was urgent, but it could wait.', 'May mắn thay, tôi nghĩ rằng email đó là khẩn cấp, nhưng nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('fortunately', 5, 'I used the word fortunately when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "may mắn thay" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('unfortunately', 1, 'Unfortunately, I''m busy.', 'Không may là tôi bận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('unfortunately', 2, 'I will unfortunately let you know when the meeting is confirmed.', 'Rất tiếc, tôi sẽ thông báo cho anh/chị khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('unfortunately', 3, 'We unfortunately check the details before sending the email.', 'Rất tiếc, chúng tôi kiểm tra thông tin trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('unfortunately', 4, 'I unfortunately thought the email was urgent, but it could wait.', 'Rất tiếc là tôi đã nghĩ email đó là khẩn cấp, nhưng hóa ra nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('unfortunately', 5, 'I used the word unfortunately when I talked with my coworker about our trip.', 'Tôi đã dùng từ "thật không may" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('luckily', 1, 'Luckily, I was home.', 'May mắn là tôi ở nhà.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('luckily', 2, 'I will luckily let you know when the meeting is confirmed.', 'Tôi sẽ thông báo cho bạn khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('luckily', 3, 'We luckily check the details before sending the email.', 'May mắn thay, chúng tôi kiểm tra thông tin trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('luckily', 4, 'I luckily thought the email was urgent, but it could wait.', 'Tôi may mắn nghĩ rằng email đó là khẩn cấp, nhưng nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('luckily', 5, 'I used the word luckily when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "may mắn thay" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('surprisingly', 1, 'Surprisingly, he agreed.', 'Ngạc nhiên là anh ấy đồng ý.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('surprisingly', 2, 'I will surprisingly let you know when the meeting is confirmed.', 'Tôi sẽ bất ngờ thông báo cho bạn khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('surprisingly', 3, 'We surprisingly check the details before sending the email.', 'Chúng tôi kiểm tra các chi tiết một cách đáng ngạc nhiên trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('surprisingly', 4, 'I surprisingly thought the email was urgent, but it could wait.', 'Tôi đã ngạc nhiên nghĩ rằng email đó là khẩn cấp, nhưng hóa ra nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('surprisingly', 5, 'I used the word surprisingly when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "một cách đáng ngạc nhiên" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('seriously', 1, 'Seriously, are you okay?', 'Nghiêm túc đấy, bạn ổn không?');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('seriously', 2, 'I will seriously let you know when the meeting is confirmed.', 'Tôi chắc chắn sẽ báo cho bạn khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('seriously', 3, 'We seriously check the details before sending the email.', 'Chúng tôi kiểm tra kỹ các chi tiết trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('seriously', 4, 'I seriously thought the email was urgent, but it could wait.', 'Tôi thực sự nghĩ rằng email đó là khẩn cấp, nhưng hóa ra nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('seriously', 5, 'I used the word seriously when I talked with my coworker about our trip.', 'Tôi đã dùng từ "thực sự" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('literally', 1, 'I literally waited 2 hours.', 'Tôi đã đợi đúng 2 tiếng luôn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('literally', 2, 'I will literally let you know when the meeting is confirmed.', 'Tôi sẽ thông báo cho bạn ngay khi cuộc họp được xác nhận.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('literally', 3, 'We literally check the details before sending the email.', 'Chúng tôi thực sự kiểm tra các chi tiết trước khi gửi email.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('literally', 4, 'I literally thought the email was urgent, but it could wait.', 'Tôi thực sự nghĩ rằng email đó là khẩn cấp, nhưng hóa ra nó có thể chờ được.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('literally', 5, 'I used the word literally when I talked with my coworker about our trip.', 'Tôi đã dùng từ "literally" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('however', 1, 'It''s expensive. However, it''s worth it.', 'Nó đắt. Tuy nhiên, nó đáng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('however', 2, 'The room is small; however, it is comfortable.', 'Căn phòng nhỏ; tuy nhiên, nó rất thoải mái.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('however', 3, 'I was busy; however, I made time to call my family.', 'Tôi bận; tuy nhiên, tôi vẫn dành thời gian để gọi cho gia đình.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('however', 4, 'The train was delayed; however, we arrived before the meeting.', 'Chuyến tàu bị trễ; tuy nhiên, chúng tôi đã đến trước cuộc họp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('however', 5, 'I used the word however when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "however" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('therefore', 1, 'I''m busy, therefore I can''t come.', 'Tôi bận, vì vậy tôi không thể đến.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('therefore', 2, 'The client approved the plan; therefore, we can begin.', 'Khách hàng đã phê duyệt kế hoạch; do đó, chúng ta có thể bắt đầu.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('therefore', 3, 'The road was closed; therefore, we took another route.', 'Con đường bị chặn; vì vậy, chúng tôi đi đường khác.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('therefore', 4, 'The train was delayed; therefore, we arrived before the meeting.', 'Chuyến tàu bị trễ; do đó, chúng tôi đã đến trước cuộc họp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('therefore', 5, 'I used the word therefore when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "do đó" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('otherwise', 1, 'Hurry up, otherwise you''ll be late.', 'Nhanh lên, nếu không bạn sẽ muộn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('otherwise', 2, 'Please save your work; otherwise, you may lose it.', 'Vui lòng lưu công việc của bạn; nếu không, bạn có thể bị mất dữ liệu.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('otherwise', 3, 'We should leave now; otherwise, we will miss the bus.', 'Chúng ta nên đi ngay bây giờ; nếu không, chúng ta sẽ lỡ chuyến xe buýt.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('otherwise', 4, 'The train was delayed; otherwise, we arrived before the meeting.', 'Chuyến tàu bị trễ; nếu không, chúng tôi đã đến trước cuộc họp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('otherwise', 5, 'I used the word otherwise when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "nếu không" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('instead', 1, 'Let''s stay home instead.', 'Thay vào đó chúng ta ở nhà đi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('instead', 2, 'We can take the train instead.', 'Thay vào đó, chúng ta có thể đi tàu hỏa.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('instead', 3, 'I planned to cook, but we ordered food instead.', 'Tôi đã định nấu ăn, nhưng thay vào đó, chúng tôi đã đặt đồ ăn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('instead', 4, 'The train was delayed; instead, we arrived before the meeting.', 'Chuyến tàu bị trễ; thay vào đó, chúng tôi đến trước cuộc họp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('instead', 5, 'I used the word instead when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "instead" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('besides', 1, 'Besides, it''s too far.', 'Ngoài ra, nó còn quá xa.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('besides', 2, 'Besides the salary, the job offers flexible hours.', 'Ngoài mức lương, công việc này còn có giờ làm việc linh hoạt.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('besides', 3, 'I do not want to go out; besides, it is getting late.', 'Tôi không muốn ra ngoài; vả lại, trời cũng đã muộn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('besides', 4, 'The train was delayed; besides, we arrived before the meeting.', 'Chuyến tàu bị trễ; hơn nữa, chúng tôi đã đến trước cuộc họp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('besides', 5, 'I used the word besides when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "besides" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('moreover', 1, 'Moreover, it''s cheaper.', 'Hơn nữa, nó còn rẻ hơn.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('moreover', 2, 'The hotel is affordable; moreover, it is close to work.', 'Khách sạn có giá cả phải chăng; hơn nữa, khách sạn còn gần nơi làm việc.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('moreover', 3, 'The new plan saves time; moreover, it is easy to follow.', 'Kế hoạch mới giúp tiết kiệm thời gian; hơn nữa, kế hoạch đó cũng dễ thực hiện.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('moreover', 4, 'The train was delayed; moreover, we arrived before the meeting.', 'Chuyến tàu bị trễ; hơn nữa, chúng tôi đã đến trước cuộc họp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('moreover', 5, 'I used the word moreover when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "hơn nữa" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('meanwhile', 1, 'Meanwhile, I''ll cook dinner.', 'Trong lúc đó, tôi sẽ nấu cơm.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('meanwhile', 2, 'I will prepare the slides; meanwhile, you can check the figures.', 'Tôi sẽ chuẩn bị các trang trình chiếu; trong khi đó, bạn có thể kiểm tra các số liệu.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('meanwhile', 3, 'The children were getting ready; meanwhile, their parents packed the car.', 'Lũ trẻ đang chuẩn bị; trong khi đó, ba mẹ chúng dọn đồ lên xe.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('meanwhile', 4, 'The train was delayed; meanwhile, we arrived before the meeting.', 'Chuyến tàu bị trễ; trong khi đó, chúng tôi đã đến trước cuộc họp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('meanwhile', 5, 'I used the word meanwhile when I talked with my coworker about our trip.', 'Tôi đã sử dụng từ "trong khi đó" khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('anyway', 1, 'Anyway, let''s move on.', 'Dù sao thì, chúng ta tiếp tục đi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('anyway', 2, 'Anyway, let us get back to the main question.', 'Dù sao, chúng ta hãy quay lại câu hỏi chính.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('anyway', 3, 'I was tired, but I finished the task anyway.', 'Tôi mệt, nhưng dù sao tôi cũng đã hoàn thành nhiệm vụ.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('anyway', 4, 'The train was delayed; anyway, we arrived before the meeting.', 'Chuyến tàu bị trễ; dù sao thì chúng tôi cũng đến trước cuộc họp.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('anyway', 5, 'I used the word anyway when I talked with my coworker about our trip.', 'Tôi đã sử dụng cụm từ anyway khi nói chuyện với đồng nghiệp về chuyến đi của chúng tôi.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('feeling', 1, 'I have a bad feeling.', 'Tôi có cảm giác không tốt.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('feeling', 2, 'We talked about the feeling during a meeting at work.', 'Chúng ta đã nói về cảm giác đó trong một cuộc họp tại nơi làm việc.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('feeling', 3, 'The feeling can influence an important decision.', 'Cảm giác có thể ảnh hưởng đến một quyết định quan trọng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('feeling', 4, 'We discussed the feeling before booking our work trip.', 'Chúng tôi đã thảo luận về cảm giác trước khi đặt chuyến công tác.');
