INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mood', 3, 'The mood can influence an important decision.', 'Tâm trạng có thể ảnh hưởng đến một quyết định quan trọng.');
INSERT INTO hard_word_examples (word, position, english, vietnamese) VALUES ('mood', 4, 'We discussed the mood before booking our work trip.', 'Chúng tôi đã thảo luận về tâm trạng trước khi đặt chuyến công tác.');
